PRAGMA foreign_keys=ON;
CREATE TABLE `events` (`id` text PRIMARY KEY NOT NULL,`title` text NOT NULL,`description` text DEFAULT '' NOT NULL,`location` text NOT NULL,`starts_at` integer NOT NULL,`ends_at` integer NOT NULL,`timezone` text DEFAULT 'America/Boise' NOT NULL,`capacity` integer NOT NULL,`status` text DEFAULT 'draft' NOT NULL CHECK (`status` IN ('draft','published','archived')),`published_at` integer,`archived_at` integer,`created_by` text NOT NULL,`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch() * 1000) NOT NULL);
CREATE INDEX `events_status_starts_idx` ON `events` (`status`,`starts_at`);
CREATE TABLE `event_rsvps` (`id` text PRIMARY KEY NOT NULL,`event_id` text NOT NULL REFERENCES `events`(`id`) ON DELETE cascade,`public_token` text NOT NULL,`status` text DEFAULT 'confirmed' NOT NULL CHECK (`status` IN ('confirmed','waitlisted','cancelled','declined')),`primary_guest_name` text NOT NULL,`email` text NOT NULL,`phone` text,`party_size` integer DEFAULT 1 NOT NULL CHECK (`party_size` > 0),`notes` text,`checked_in_at` integer,`no_show_at` integer,`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch() * 1000) NOT NULL);
CREATE UNIQUE INDEX `event_rsvps_public_token_unique` ON `event_rsvps` (`public_token`);
CREATE INDEX `event_rsvps_event_status_idx` ON `event_rsvps` (`event_id`,`status`);
CREATE TABLE `event_guests` (`id` text PRIMARY KEY NOT NULL,`rsvp_id` text NOT NULL REFERENCES `event_rsvps`(`id`) ON DELETE cascade,`name` text NOT NULL,`checked_in_at` integer,`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL);
CREATE INDEX `event_guests_rsvp_idx` ON `event_guests` (`rsvp_id`);
CREATE TABLE `event_appointment_slots` (`id` text PRIMARY KEY NOT NULL,`event_id` text NOT NULL REFERENCES `events`(`id`) ON DELETE cascade,`rsvp_id` text REFERENCES `event_rsvps`(`id`) ON DELETE set null,`starts_at` integer NOT NULL,`ends_at` integer NOT NULL,`label` text,`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL, CHECK (`ends_at` > `starts_at`));
CREATE UNIQUE INDEX `event_appointment_slots_event_start_unique` ON `event_appointment_slots` (`event_id`,`starts_at`);
CREATE INDEX `event_appointment_slots_event_range_idx` ON `event_appointment_slots` (`event_id`,`starts_at`,`ends_at`);
CREATE TABLE `event_check_ins` (`id` text PRIMARY KEY NOT NULL,`event_id` text NOT NULL REFERENCES `events`(`id`) ON DELETE cascade,`rsvp_id` text NOT NULL REFERENCES `event_rsvps`(`id`) ON DELETE cascade,`guest_id` text REFERENCES `event_guests`(`id`) ON DELETE cascade,`action` text NOT NULL CHECK (`action` IN ('checked_in','no_show','undo')),`actor_email` text NOT NULL,`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL);
CREATE INDEX `event_check_ins_event_idx` ON `event_check_ins` (`event_id`,`created_at`);
